-- Seed built-in starter prompts into Cloudflare D1
INSERT OR IGNORE INTO prompts (id, title, text, cats, image, published, created_at) VALUES
('golden-hour-portrait', 'Golden hour portrait', 'Edit my photo into a golden hour portrait. Warm sunlight from behind, soft rim light on the hair, gentle lens flare, natural skin texture and shallow depth of field. Keep my face, hairstyle and proportions exactly the same. Vertical 4:5 for Instagram.', 'trending portrait', NULL, 1, '2026-10-01T00:00:20Z'),
('cinematic-couple-street', 'Cinematic couple on a neon street', 'Transform this photo of two people into a cinematic night street scene with neon reflections on wet pavement. Keep both faces, outfits and body language unchanged. Add soft teal and orange color grading, subtle film grain and a 35mm look. Vertical 4:5.', 'couple trending', NULL, 1, '2026-10-01T00:00:19Z'),
('couple-sunset-beach', 'Couple at sunset beach', 'Place the couple in my photo on a quiet beach at sunset. Warm pink and orange sky, gentle waves, soft light on both faces. Keep both people recognizable with the same faces, skin tones and poses. Realistic, romantic and uncluttered.', 'couple', NULL, 1, '2026-10-01T00:00:18Z'),
('minimal-studio-portrait', 'Minimal studio portrait', 'Edit this photo into a clean studio portrait on a seamless light grey backdrop. Soft box lighting, natural skin retouching, sharp eyes, no heavy smoothing. Keep my face and expression unchanged. Square 1:1.', 'portrait', NULL, 1, '2026-10-01T00:00:17Z'),
('magazine-cover-text', 'Magazine cover with text', 'Turn my photo into a magazine-style cover. Add the headline "YOUR TEXT HERE" in bold sans-serif at the top and a small subtitle at the bottom. Keep my face fully visible and not covered by any text. Soft studio lighting and muted colors.', 'text trending', NULL, 1, '2026-10-01T00:00:16Z'),
('quote-overlay', 'Quote overlay in handwriting', 'Add the quote "YOUR QUOTE HERE" in elegant handwritten lettering in the lower third of my photo. White text with a soft shadow so it stays readable. Slightly darken the lower background and keep faces and the main subject untouched.', 'text', NULL, 1, '2026-10-01T00:00:15Z'),
('hand-painted-anime', 'Hand-painted anime frame', 'Redraw my photo as a hand-painted anime film frame. Soft watercolor sky, painterly clouds, gentle outlines and a warm natural palette. Keep my pose, outfit and the likeness of my face.', 'style trending', NULL, 1, '2026-10-01T00:00:14Z'),
('vintage-film', '90s disposable camera', 'Give this photo the look of a 1990s disposable camera. Direct flash, slightly faded colors, soft grain, small light leaks and a warm date-stamp feel. Do not change faces or poses.', 'style trending', NULL, 1, '2026-10-01T00:00:13Z'),
('cafe-background', 'Cozy cafe background', 'Replace only the background with a cozy window-side cafe in soft morning light. Match the lighting direction on my face. Keep my face, clothes and the edges of my hair exactly as they are. Natural, realistic result.', 'background', NULL, 1, '2026-10-01T00:00:12Z'),
('remove-crowd', 'Remove people in the background', 'Remove all strangers and clutter from the background and fill the space with natural scenery that matches the light and perspective. Do not blur or alter the main subject. Keep the original color tones.', 'background', NULL, 1, '2026-10-01T00:00:11Z'),
('festival-lights-couple', 'Festive lights couple', 'Edit this couple photo into a festive evening scene with warm string lights and soft bokeh. Keep clothes, faces and skin tones the same. Add a gentle glow, a calm mood and a vertical 9:16 crop for Stories.', 'couple', NULL, 1, '2026-10-01T00:00:10Z'),
('bw-moody-portrait', 'Moody black and white', 'Convert my photo into a moody black and white portrait with deep shadows, strong contrast and fine film grain. Dramatic side lighting, sharp eyes, natural skin texture. Keep my face unchanged.', 'portrait style', NULL, 1, '2026-10-01T00:00:09Z'),
('tiny-collectible', 'Collectible figure style', 'Create a glossy, collectible-style figure of the person in my photo standing on a small round display base. Clean studio backdrop, soft reflections, accurate clothing colors and a face that clearly resembles me. Square 1:1.', 'trending style', NULL, 1, '2026-10-01T00:00:08Z'),
('rainy-city-couple', 'Rainy city evening couple', 'Edit this couple photo into a rainy evening in a city. Shared umbrella, soft street lights reflecting on wet pavement, gentle mist and a calm romantic mood. Keep both faces, hairstyles and clothes unchanged and make sure neither person is hidden by the umbrella.', 'couple', NULL, 1, '2026-10-01T00:00:07Z'),
('polaroid-couple', 'Instant film couple portrait', 'Turn this couple photo into an instant-film print with a white border, slightly faded colors, soft flash and a handwritten caption line that says "US, 2026". Keep both faces natural and recognizable and do not change body proportions.', 'couple style', NULL, 1, '2026-10-01T00:00:06Z'),
('birthday-card-text', 'Birthday card with name', 'Turn my photo into a birthday card. Add the text "HAPPY BIRTHDAY, NAME" in playful rounded lettering above my head, with small confetti around the edges. Keep my face and expression untouched, and keep every letter spelled exactly as written.', 'text', NULL, 1, '2026-10-01T00:00:05Z'),
('travel-poster-text', 'Travel poster with title', 'Edit my photo into a vintage travel poster. Add the title "VISIT YOUR CITY" in bold condensed letters at the bottom on a solid color band, flatten the colors slightly and add a subtle paper texture. Keep my face clear and recognizable.', 'text trending', NULL, 1, '2026-10-01T00:00:04Z'),
('polaroid-collage', 'Three-frame photo collage', 'Arrange my photo into a collage of three instant-film frames on a soft beige table, each frame showing a slightly different crop of the same image. Gentle shadows, natural light from a window and no changes to my face in any frame. Vertical 4:5.', 'trending style', NULL, 1, '2026-10-01T00:00:03Z'),
('pro-headshot', 'Professional headshot', 'Turn my casual photo into a professional headshot. Neutral blurred office background, soft front lighting, tidy collar and hair, natural skin texture without over-smoothing. Keep my face, age and expression exactly the same. Square 1:1.', 'portrait', NULL, 1, '2026-10-01T00:00:02Z'),
('comic-panel', 'Comic book panel', 'Redraw my photo as a single comic book panel with bold ink outlines, halftone shading and a flat color palette. Keep my pose, outfit and face shape recognizable, and leave a small empty speech bubble in the upper corner.', 'style trending', NULL, 1, '2026-10-01T00:00:01Z');
